package com.vectoragent.phone;
import android.app.Activity;import android.os.Bundle;import android.graphics.Color;import android.widget.*;
public class MultiAgentActivity extends Activity{
 private MultiAgentEngine engine;private LinearLayout root;private TextView dashboard,trace,history;private EditText topic;
 int dp(int v){return(int)(v*getResources().getDisplayMetrics().density+.5f);} TextView tv(String s,float z){TextView t=new TextView(this);t.setText(s);t.setTextSize(z);t.setTextColor(Color.rgb(35,35,40));t.setPadding(dp(8),dp(7),dp(8),dp(7));return t;} Button btn(String s){Button b=new Button(this);b.setText(s);b.setAllCaps(false);return b;}
 public void onCreate(Bundle b){super.onCreate(b);engine=new MultiAgentEngine(this,new MemoryStore(this));ScrollView sc=new ScrollView(this);root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setPadding(dp(12),dp(10),dp(12),dp(18));sc.addView(root);setContentView(sc);build();}
 void build(){root.addView(tv("🧪 VECTOR LAB 2.1",26));root.addView(tv("Реальная цепочка: задача → Исследователь → Скептик → Экспериментатор → наблюдение → Судья → предсказание. Все циклы сохраняются в SQLite.",13));dashboard=tv("",14);root.addView(dashboard);root.addView(tv("Текущая задача",18));topic=new EditText(this);topic.setHint("Например: A=2, B=4, C=6. Предскажи D.");topic.setMinLines(2);root.addView(topic);LinearLayout a=new LinearLayout(this);Button run=btn("▶ Запустить цикл"),clear=btn("↺ Очистить Bus/World");a.addView(run,new LinearLayout.LayoutParams(0,-2,1));a.addView(clear,new LinearLayout.LayoutParams(0,-2,1));root.addView(a);root.addView(tv("Агенты",18));root.addView(tv("🔎 Исследователь — строит правило\n🥊 Скептик — ищет контрпример\n🔬 Экспериментатор — строит проверку\n⚖ Судья — выносит verdict и prediction",14));root.addView(tv("Последний цикл",18));trace=tv("Пока не запускался.",13);root.addView(trace);root.addView(tv("Постоянный журнал циклов",18));history=tv("",12);root.addView(history);run.setOnClickListener(v->{MultiAgentEngine.Cycle c=engine.runCycle(topic.getText().toString());trace.setText("Цикл #"+c.number+"\n\n🔎 "+c.hypothesis+"\n\n🥊 "+c.challenge+"\n\n🔬 "+c.experiment+"\n\n📊 "+c.evidence+"\n\n⚖ "+c.judgement+"\n\n🎯 "+c.prediction+"\nУверенность: "+Math.round(c.confidence*100)+"%");refresh();});clear.setOnClickListener(v->{engine.clearRuntime();refresh();});refresh();}
 void refresh(){dashboard.setText(engine.dashboard());history.setText(engine.recentCycles(8));}
}